describe('JavaScript Alert Confirmation', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
  });

  it('should display confirm dialog and record user choice', () => {
    // Verify initial page state
    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Welcome to JavaScript Alerts');

    // Click the confirm button to open the native confirm dialog
    cy.get('[data-testid="Click for JS Confirm"]').click();

    // Verify confirm dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Confirm');

    // Intercept the confirmation API call
    cy.intercept('POST', '/api/confirm').as('confirmDialog');

    // Click 'OK' button
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-ok"]').click();
    });

    // Wait for the API call to complete
    cy.wait('@confirmDialog');

    // Verify result element shows 'You clicked: Ok'
    cy.get('#result').should('be.visible');
    cy.get('#result').should('contain', 'You clicked: Ok');

    // Verify flash messages are updated
    cy.get('#flash-messages').should('contain', 'Confirmation successful');
  });

  it('should display cancel dialog and record user choice on second click', () => {
    // Verify initial page state
    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Welcome to JavaScript Alerts');

    // Click the confirm button to open the native confirm dialog
    cy.get('[data-testid="Click for JS Confirm"]').click();

    // Verify confirm dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Confirm');

    // Intercept the confirmation API call
    cy.intercept('POST', '/api/confirm').as('confirmDialog');

    // Click 'OK' button
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-ok"]').click();
    });

    // Wait for the API call to complete
    cy.wait('@confirmDialog');

    // Verify result element shows 'You clicked: Ok'
    cy.get('#result').should('be.visible');
    cy.get('#result').should('contain', 'You clicked: Ok');

    // Verify flash messages are updated
    cy.get('#flash-messages').should('contain', 'Confirmation successful');

    // Click the confirm button again to open the dialog
    cy.get('[data-testid="Click for JS Confirm"]').click();

    // Verify confirm dialog appears again
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');

    // Click 'Cancel' button
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-cancel"]').click();
    });

    // Wait for the API call to complete
    cy.wait('@confirmDialog');

    // Verify result element shows 'You clicked: Cancel'
    cy.get('#result').should('be.visible');
    cy.get('#result').should('contain', 'You clicked: Cancel');

    // Verify flash messages are updated
    cy.get('#flash-messages').should('contain', 'Confirmation cancelled');
  });
});
